// Expo config plugin: add the "Log bank message" App Intent (Swift) to the iOS app
// target, so Seshat shows up as a native action inside the Shortcuts app.
//
// ios/ is generated by `expo prebuild`, so the Swift file lives in plugins/ios/ and
// is copied into the project (and added to the app target) on every prebuild.
const { withDangerousMod, withXcodeProject, IOSConfig } = require('@expo/config-plugins');
const fs = require('fs');
const path = require('path');

const FILE = 'SeshatAppIntents.swift';

function withCopy(config) {
  return withDangerousMod(config, [
    'ios',
    (cfg) => {
      const src = path.join(cfg.modRequest.projectRoot, 'plugins', 'ios', FILE);
      const dir = path.join(cfg.modRequest.platformProjectRoot, cfg.modRequest.projectName);
      fs.mkdirSync(dir, { recursive: true });
      fs.copyFileSync(src, path.join(dir, FILE));
      return cfg;
    },
  ]);
}

function withTarget(config) {
  return withXcodeProject(config, (cfg) => {
    const project = cfg.modResults;
    const name = cfg.modRequest.projectName;
    const rel = `${name}/${FILE}`;
    if (!project.hasFile(rel)) {
      IOSConfig.XcodeUtils.addBuildSourceFileToGroup({ filepath: rel, groupName: name, project });
    }
    return cfg;
  });
}

module.exports = (config) => withTarget(withCopy(config));
